import { describe, it, expect } from "vitest";
import { runScenario } from "./claim-office.js";

describe("MHPCO Claim Office", () => {
  // --- Quote: base premiums for main items ---
  it.todo("empty item list → premium 5 G (only the processing fee)");
  it.todo("a sword → base premium 100 G, premium 115 G (100 + 10 first insurance + 5 fee)");
  it.todo("an amulet → base premium 60 G");
  it.todo("a staff → base premium 80 G");
  it.todo("a potion → base premium 40 G");

  // --- Quote: components and building blocks ---
  it.todo("a single rune → base premium 25 G");
  it.todo("2 runes → 50 G base premium");
  it.todo("3 runes → 60 G base premium (block applies)");
  it.todo("4 runes → 100 G base premium (no block — block requires exactly 3)");
  it.todo("7 runes → 175 G base premium");
  it.todo("2 runes + 1 moonstone → 75 G base premium (no block: different types)");
  it.todo("3 runes + 3 moonstones → 120 G base premium (two separate blocks)");

  // --- Quote: item-scoped modifiers ---
  it.todo("cursed sword → 50 % surcharge on that item's base premium");
  it.todo("sword with enchantment 5 → high-enchantment surcharge applies (30 %)");
  it.todo("sword with enchantment 4 → no high-enchantment surcharge");
  it.todo("cursed sword with enchantment 5 → both surcharges apply");

  // --- Quote: policy-scoped modifiers ---
  it.todo("customer with exactly 2 years with MHPCO → 20 % loyalty discount applies");
  it.todo("customer with 1 year with MHPCO → no loyalty discount");
  it.todo("first insurance adds 10 % of the policy base premium");
  it.todo("second quote in a scenario → 15 % follow-up contract discount on policy base premium");

  // --- Quote: modifier scope on multi-item policies ---
  it.todo("cursed sword + plain amulet → policy base 160 G, curse adds 50 G → 210 G before further modifiers and fee");

  // --- Quote: rounding ---
  it.todo("a premium calculation that yields 197.5 G → final premium 198 G (rounded up)");

  // --- Quote: integration examples ---
  it.todo("newcomer with a cursed sword (steel, enchantment 3), 0 years → premium 165 G");
  it.todo("long-standing customer (3 years), second quote, cursed sword enchantment 7 → premium 160 G");

  // --- Claim: basic reimbursement and deductible ---
  it.todo("regular sword (steel, enchantment 3), damage 500 G → payout 400 G");
  it.todo("damage to a rune (value 250 G), damage 200 G → payout 100 G");
  it.todo("dragon attack damaging sword (500 G) and amulet (300 G) → payout 600 G (deductible per damaged item)");

  // --- Claim: special clauses ---
  it.todo("dragon-material sword, enchantment 5, damage 800 G → payout 700 G (full reimbursement, then deductible)");
  it.todo("steel sword, enchantment 9, damage 1000 G → payout 400 G (50 % first, then deductible)");
  it.todo("dragon-material sword, enchantment 9, damage 1000 G → payout 400 G (50 % rule wins, then deductible)");
  it.todo("dragon-material sword with exactly enchantment 8, damage 1000 G → payout 400 G");

  // --- Claim: rounding ---
  it.todo("a payout calculation that yields 350.5 G → final payout 350 G (rounded down)");

  // --- Claim: cap ---
  it.todo("policy covering a sword and an amulet → insurance sum 1600 G, cap 3200 G");
  it.todo("cursed sword (premium with modifiers 165 G) → cap 2000 G (premium modifiers do not raise the cap)");
  it.todo("policy covering a sword and 3 runes (a block) → insurance sum 1750 G, cap 3500 G");
  it.todo("sword policy (cap 2000 G), first claim of 1500 G → payout 1400 G, remainingCap 600 G");
  it.todo("sword policy, second claim of 1500 G after the first → payout 600 G, remainingCap 0 G");

  // --- Claim: multiple items of the same type ---
  it.todo("policy covering two swords → insurance sum 2000 G, cap 4000 G");
  it.todo("two sword damage entries against a two-sword policy → each entry gets its own deductible");

  // --- Error cases ---
  it.todo("quote with an unknown item type (e.g. broomstick) → error, no results");
  it.todo("claim damaging an item not part of the policy (amulet when only a sword is insured) → error");
  it.todo("claim damaging an item with an unknown type → error");
  it.todo("more damage entries of a type than the policy covers (two sword damages, one sword insured) → error");
  it.todo("claim with a damage entry of amount -200 → error");

  // --- CLI ---
  it.todo("CLI reads the schema example scenario from stdin and writes results to stdout");
  it.todo("CLI exits with a non-zero status and writes an error to stderr for an unknown item type");
});

