export interface Scenario {
  customer: { yearsWithMHPCO: number };
  steps: Step[];
}

export type Step = QuoteStep | ClaimStep;

export interface QuoteStep {
  op: "quote";
  items: Item[];
}

export interface Item {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
}

export interface ClaimStep {
  op: "claim";
  policy: number;
  incident: Incident;
}

export interface Incident {
  cause: string;
  damages: Damage[];
}

export interface Damage {
  itemType: string;
  amount: number;
}

export type Result = { premium: number } | { payout: number; remainingCap: number };

const PROCESSING_FEE = 5;

const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;

const BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: 25,
};

/** Premiums round in the MHPCO's favour: always up. */
const roundPremium = (premium: number): number => Math.ceil(premium);

const policyBasePremiumOf = (items: Item[]): number =>
  items.reduce((sum, item) => sum + (BASE_PREMIUMS[item.type] ?? 0), 0);

const quote = (step: QuoteStep): Result => {
  const policyBasePremium = policyBasePremiumOf(step.items);
  const firstInsuranceSurcharge = policyBasePremium * FIRST_INSURANCE_SURCHARGE_RATE;
  return {
    premium: roundPremium(policyBasePremium + firstInsuranceSurcharge + PROCESSING_FEE),
  };
};

const resultOf = (step: Step): Result => {
  if (step.op === "quote") return quote(step);
  throw new Error(`Unsupported operation: ${step.op}`);
};

export const runScenario = (scenario: Scenario): { results: Result[] } => ({
  results: scenario.steps.map(resultOf),
});

