/** Premiums round in the MHPCO's favour: always up. */
const roundPremium = (premium: number): number => Math.ceil(premium);

/**
 * Exactly this many items of one type form a "building block", priced at a flat
 * rate instead of per item. A larger group is NOT a block -- 4 runes pay 4x25 G.
 */
const BLOCK_SIZE = 3;
const BLOCK_BASE_PREMIUM = 60;

/** How many items of each type the policy covers -- the unit the block rule applies to. */
const countItemsPerType = (items: Item[]): Map<string, number> =>
  items.reduce(
    (counts, item) => counts.set(item.type, (counts.get(item.type) ?? 0) + 1),
    new Map<string, number>(),
  );

/** Unknown types price at 0 G for now; the spec calls for an error (not yet tested). */
const basePremiumPerItem = (type: string): number => BASE_PREMIUMS[type] ?? 0;

const basePremiumForType = (type: string, count: number): number =>
  count === BLOCK_SIZE ? BLOCK_BASE_PREMIUM : count * basePremiumPerItem(type);

const policyBasePremium = (items: Item[]): number =>
  [...countItemsPerType(items)].reduce(
    (total, [type, count]) => total + basePremiumForType(type, count),
    0,
  );

const quote = (step: QuoteStep): Result => {
  const basePremium = policyBasePremium(step.items);
  const firstInsuranceSurcharge = basePremium * FIRST_INSURANCE_SURCHARGE_RATE;
  return {
    premium: roundPremium(basePremium + firstInsuranceSurcharge + PROCESSING_FEE),
  };
};

const resultOf = (step: Step): Result => {
  if (step.op === "quote") return quote(step);
  throw new Error(`Unsupported operation: ${step.op}`);
};

export const runScenario = (scenario: Scenario): { results: Result[] } => ({
  results: scenario.steps.map(resultOf),
});

