/**
 * Policy-scoped modifiers apply to the policy base premium, never to item
 * surcharges. They combine additively, like the item-scoped ones. So far only
 * the first-insurance surcharge is implemented; the loyalty and follow-up
 * discounts join this sum as negative rates.
 *
 * Returns the surcharge AMOUNT, not a multiplier on the base. Folding this into
 * `policyBase * (1 + rate)` is algebraically identical but NOT identical in
 * floating point: 100 * 1.1 is 110.00000000000001, which `roundPremium` ceils
 * to 111 G. Keeping base and surcharge as separate addends keeps the exact
 * values the spec's worked examples expect.
 */
const policyModifierTotal = (policyBase: number): number =>
  policyBase * FIRST_INSURANCE_SURCHARGE_RATE;

const quote = (step: QuoteStep): Result => {
  const policyBase = policyBasePremium(step.items);
  return {
    premium: roundPremium(
      policyBase +
        policyModifierTotal(policyBase) +
        itemSurchargeTotal(step.items) +
        PROCESSING_FEE,
    ),
  };
};

