p='src/claim-office.ts'
s=open(p).read()
s=s.replace("""const runStep = (step: Step, scenario: Scenario, precedingSteps: Step[]): Result => {
  if (step.op !== "quote") throw new Error(`Unsupported operation: ${step.op}`);
  return quote(step, scenario.customer, isFollowUpContract(precedingSteps));
