"""const INSURANCE_VALUES: Record<string, number> = {
  sword: 1000,
  amulet: 600,
  staff: 800,
  potion: 400,
  rune: 250,
  moonstone: 250,
};

const DEDUCTIBLE_PER_DAMAGE = 100;
const CAP_MULTIPLE_OF_INSURANCE_SUM = 2;

const insuranceSum = (items: Item[]): number =>
  items.reduce((sum, item) => sum + (INSURANCE_VALUES[item.type] ?? 0), 0);

/** A policy, once quoted, tracks how much of its cap is still available. */
interface Policy {
  items: Item[];
  remainingCap: number;
}

/** Payouts round in the MHPCO's favour: always down. */
const roundPayout = (payout: number): number => Math.floor(payout);

const claim = (step: ClaimStep, policy: Policy): Result => {
  const desired = step.incident.damages.reduce(
    (total, damage) => total + Math.max(damage.amount - DEDUCTIBLE_PER_DAMAGE, 0),
    0,
  );
  const payout = roundPayout(Math.min(desired, policy.remainingCap));
  policy.remainingCap -= payout;
  return { payout, remainingCap: policy.remainingCap };
};

export const runScenario = (scenario: Scenario): { results: Result[] } => {
  const policies = new Map<number, Policy>();
  const results: Result[] = [];

  scenario.steps.forEach((step, stepIndex) => {
    if (step.op === "quote") {
      results.push(
        quote(step, scenario.customer, isFollowUpContract(scenario.steps.slice(0, stepIndex))),
      );
      policies.set(stepIndex, {
        items: step.items,
        remainingCap: insuranceSum(step.items) * CAP_MULTIPLE_OF_INSURANCE_SUM,
      });
      return;
    }
    const policy = policies.get(step.policy);
    if (!policy) throw new Error(`No policy created by step ${step.policy}`);
    results.push(claim(step, policy));
  });

  return { results };
};""")
