        itemSurchargeTotal(items) +
        PROCESSING_FEE,
    ),
  };
};
const anInsuredItemOfDamagedType = (items: Item[], damage: Damage): Item =>
  items.find((item) => item.type === damage.itemType) ?? { type: damage.itemType };

/**
 * What one damage entry earns: the insured item it hit sets the reimbursement
 * rate, and each entry carries its own deductible. Never pays out negative.
 */
const reimbursementForDamage = (damage: Damage, insuredItem: Item): number =>
  Math.max(damage.amount * reimbursementRate(insuredItem) - DEDUCTIBLE_PER_DAMAGE, 0);

/**
 * What an incident earns against the items a policy covers, before the cap:
 * every damage entry it lists, reimbursed and summed.
 */
const reimbursementForIncident = (incident: Incident, insuredItems: Item[]): number =>
  incident.damages.reduce(
    (total, damage) =>
      total + reimbursementForDamage(damage, anInsuredItemOfDamagedType(insuredItems, damage)),
    0,
  );

